// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
} from '../remotionShim';
// Load Inter font for a clean, modern UI look
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const { fontFamily: interFamily } = loadInter();



export type ReviewNotificationProps = Record<string, any>;

const StarIcon: React.FC<{ size: number; color: string }> = ({ size, color }) => (
  <svg
    width={size}
    height={size}
    viewBox="0 0 24 24"
    style={{ transition: "none" }}
  >
    <rect width="24" height="24" fill={color} />
    <path 
      fill="#ffffff" 
      d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z" 
    />
  </svg>
);

const ReviewNotification: React.FC<ReviewNotificationProps> = ({
  backgroundColor = "#f3f4f6",
  transparentBackground = false,
  durationInSeconds = 5,
  ratingText = "Excellent",
  starColor = "#00b67a",
  pillBackgroundColor = "#ffffff",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors for background color
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive sizing calculations optimized for 16:9 canvas
  const s = Math.min(width, height);
  const paddingY = s * 0.04;
  const paddingX = s * 0.06;
  const starSize = s * 0.065;
  const textSize = s * 0.055;
  const starGap = s * 0.008;
  const pillGap = s * 0.03;

  // Animation Timeline Logic
  const totalFrames = fps * durationInSeconds;
  const fadeOutStart = totalFrames - fps; // Start fading out 1 second before end

  // Slide-in Spring Animation
  const slideIn = spring({
    frame,
    fps,
    config: {
      damping: 14,
      stiffness: 90,
      mass: 0.8,
    },
  });

  // Calculate Entry Interpolations
  const yOffset = interpolate(slideIn, [0, 1], [height * 0.15, 0]);
  const scale = interpolate(slideIn, [0, 1], [0.85, 1]);
  const entryOpacity = interpolate(slideIn, [0, 0.5, 1], [0, 0.8, 1], {
    extrapolateRight: "clamp",
  });

  // Calculate Exit Interpolation
  const exitOpacity = interpolate(
    frame,
    [fadeOutStart, fadeOutStart + fps * 0.5],
    [1, 0],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  const finalOpacity = Math.min(entryOpacity, exitOpacity);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        justifyContent: "center",
        alignItems: "center",
        transition: "none",
      }}
    >
      <div
        style={{
          backgroundColor: pillBackgroundColor,
          padding: `${paddingY}px ${paddingX}px`,
          borderRadius: "999px", // Pill shape
          display: "flex",
          flexDirection: "row", // Horizontal pill layout
          alignItems: "center",
          boxShadow: "0px 24px 48px rgba(0, 0, 0, 0.08), 0px 4px 12px rgba(0, 0, 0, 0.04)",
          opacity: finalOpacity,
          transform: `translateY(${yOffset}px) scale(${scale})`,
          gap: `${pillGap}px`,
          transition: "none",
        }}
      >
        {/* Left: 5 Stars */}
        <div style={{ display: "flex", gap: `${starGap}px`, transition: "none" }}>
          {[1, 2, 3, 4, 5].map((starIndex) => (
            <StarIcon key={starIndex} size={starSize} color={starColor} />
          ))}
        </div>

        {/* Right: Rating Text */}
        <span
          style={{
            fontSize: textSize,
            fontWeight: 700,
            color: "#111827",
            lineHeight: 1,
            letterSpacing: "-0.02em",
            transition: "none",
          }}
        >
          {ratingText}
        </span>
      </div>
    </AbsoluteFill>
  );
};

export default ReviewNotification;